import React, { useEffect, useState } from "react";
import {
  View, Text, StyleSheet, TextInput, TouchableOpacity,
  ScrollView, Alert, SafeAreaView, KeyboardAvoidingView,
  Platform, StatusBar, ActivityIndicator
} from "react-native";
import axios from "axios";
import { useRouter } from "expo-router";
import { Feather } from "@expo/vector-icons";
import AsyncStorage from "@react-native-async-storage/async-storage";

// PALETA DE COLORES GLAZE (Emerald & Silver)
const COLORS = {
  dark: "#0a3d2e",    // Deep Emerald
  accent: "#1f6f54",  // Lighter Emerald
  silver: "#94a3b8",  // Silver/Gray
  bg: "#fcfdfd",      // Marble White
  border: "#f1f5f9",  // Soft Divider
  white: "#ffffff"
};

export default function Perfil() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [cargandoDatos, setCargandoDatos] = useState(true);
  
  // Estado del usuario (Sincronizado con la base de datos)
  const [usuario, setUsuario] = useState({
    id_usuario: null,
    nombre_completo: "",
    correo: "",
    celular: "", // Aseguramos que se use 'celular' y no 'telefono'
    direccion: ""
  });

  const [passwordData, setPasswordData] = useState({
    password_actual: "", 
    password: ""
  });

  useEffect(() => {
    cargarDatos();
  }, []);

  const cargarDatos = async () => {
    try {
      setCargandoDatos(true);
      const usuarioRaw = await AsyncStorage.getItem("usuario");
      if (!usuarioRaw) {
        router.replace("/login");
        return;
      }
      const user = JSON.parse(usuarioRaw);
      
      // GET - Usando la ruta pluralizada corregida
      const res = await axios.get(`http://192.168.1.9:3000/api/usuarios/${user.id_usuario}`);
      
      // Seteamos los datos (el backend devuelve 'celular' y 'nombre_completo')
      setUsuario(res.data);
    } catch (error) {
      console.error("Error cargando perfil:", error);
      Alert.alert("Error", "No se pudo conectar con el servidor.");
    } finally {
      setCargandoDatos(false);
    }
  };

  const guardarCambios = async () => {
    // Validación de campos obligatorios para evitar Error 400
    if (!usuario.correo || !usuario.celular) {
      Alert.alert("Glaze", "El correo y el celular son obligatorios.");
      return;
    }

    try {
      setLoading(true);
      
      // Payload exacto como lo espera el controlador del backend
      const datosAActualizar = {
        correo: usuario.correo.trim(),
        celular: usuario.celular.toString().trim(),
        direccion: usuario.direccion ? usuario.direccion.trim() : ""
      };

      await axios.put(
        `http://192.168.1.9:3000/api/usuarios/actualizar/${usuario.id_usuario}`, 
        datosAActualizar
      );
      
      Alert.alert("EXITO", "Información actualizada correctamente.");
    } catch (error) {
      console.error("Error 400 detalle:", error.response?.data);
      const msg = error.response?.data?.error || "Error al actualizar los datos.";
      Alert.alert("Glaze Error", msg);
    } finally {
      setLoading(false);
    }
  };

  const actualizarPassword = async () => {
    if (!passwordData.password || !passwordData.password_actual) {
      Alert.alert("Atención", "Complete los campos de seguridad.");
      return;
    }
    try {
      setLoading(true);
      await axios.put(`http://192.168.1.9:3000/api/usuarios/password/${usuario.id_usuario}`, passwordData);
      Alert.alert("Seguridad", "Credenciales actualizadas exitosamente.");
      setPasswordData({ password_actual: "", password: "" });
    } catch (error) {
      Alert.alert("Error", error.response?.data?.error || "La contraseña actual no es válida.");
    } finally {
      setLoading(false);
    }
  };

  if (cargandoDatos) {
    return (
      <View style={[styles.mainWrapper, { justifyContent: 'center' }]}>
        <ActivityIndicator size="large" color={COLORS.dark} />
      </View>
    );
  }

  return (
    <SafeAreaView style={styles.mainWrapper}>
      <StatusBar barStyle="dark-content" />
      
      <View style={styles.navHeader}>
        <TouchableOpacity onPress={() => router.back()}>
          <Feather name="chevron-left" size={26} color={COLORS.dark} />
        </TouchableOpacity>
        <Text style={styles.navTitle}>BÓVEDA DE SOCIO</Text>
        <View style={{ width: 26 }} />
      </View>

      <KeyboardAvoidingView behavior={Platform.OS === "ios" ? "padding" : "height"} style={{ flex: 1 }}>
        <ScrollView style={styles.container} showsVerticalScrollIndicator={false}>
          
          <View style={styles.headerSection}>
            <Text style={styles.brandTitle}>Mi Perfil</Text>
            <View style={styles.accentLine} />
            <Text style={styles.brandSubtitle}>GESTIÓN DE DATOS PERSONALES</Text>
          </View>

          {/* TARJETA DE INFORMACIÓN */}
          <View style={styles.glazeCard}>
            <View style={styles.sideIndicator} />
            <View style={styles.cardPadding}>
              <Text style={styles.sectionLabel}>DATOS DE CONTACTO</Text>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>NOMBRE COMPLETO</Text>
                <TextInput
                  style={[styles.input, styles.inputBlocked]}
                  value={usuario.nombre_completo?.toUpperCase()}
                  editable={false}
                />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>CORREO ELECTRÓNICO</Text>
                <TextInput
                  style={styles.input}
                  value={usuario.correo}
                  onChangeText={(t) => setUsuario({...usuario, correo: t})}
                  keyboardType="email-address"
                  autoCapitalize="none"
                />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>CELULAR</Text>
                <TextInput
                  style={styles.input}
                  value={usuario.celular}
                  onChangeText={(t) => setUsuario({...usuario, celular: t})}
                  keyboardType="numeric"
                />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>DIRECCIÓN</Text>
                <TextInput
                  style={styles.input}
                  value={usuario.direccion}
                  onChangeText={(t) => setUsuario({...usuario, direccion: t})}
                />
              </View>

              <TouchableOpacity style={styles.btnMain} onPress={guardarCambios} disabled={loading}>
                {loading ? <ActivityIndicator color="white" /> : <Text style={styles.btnMainText}>ACTUALIZAR DATOS</Text>}
              </TouchableOpacity>
            </View>
          </View>

          {/* TARJETA DE SEGURIDAD */}
          <View style={styles.glazeCard}>
            <View style={[styles.sideIndicator, { backgroundColor: COLORS.silver }]} />
            <View style={styles.cardPadding}>
              <Text style={styles.sectionLabel}>SEGURIDAD DE CUENTA</Text>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>CONTRASEÑA ACTUAL</Text>
                <TextInput
                  style={styles.input}
                  secureTextEntry
                  value={passwordData.password_actual}
                  onChangeText={(t) => setPasswordData({...passwordData, password_actual: t})}
                />
              </View>

              <View style={styles.inputBox}>
                <Text style={styles.fieldLabel}>NUEVA CONTRASEÑA</Text>
                <TextInput
                  style={styles.input}
                  secureTextEntry
                  value={passwordData.password}
                  onChangeText={(t) => setPasswordData({...passwordData, password: t})}
                />
              </View>

              <TouchableOpacity style={styles.btnSecondary} onPress={actualizarPassword} disabled={loading}>
                <Text style={styles.btnSecondaryText}>CAMBIAR CONTRASEÑA</Text>
              </TouchableOpacity>
            </View>
          </View>

          <View style={{ height: 50 }} />
        </ScrollView>
      </KeyboardAvoidingView>
    </SafeAreaView>
  );
}

